    LEFT JOIN LABPROD.NMLOPROC ON PRO_KEYPRO = MOV_KEYPRO
    LEFT JOIN LABPROD.NMCOEMPL ON EMP_KEYPRO = MOV_KEYPRO AND EMP_KEYEMP = MOV_KEYEMP 
    LEFT JOIN LABPROD.GLCOPAMS ON PAM_KEYPAR = 'IEST' AND PAM_CVESEC = EMP_CA1AUX
    LEFT JOIN LABPROD.NMCODEPS ON DEP_KEYDEP = MOV_KEYDEP
    LEFT JOIN LABPROD.NMCOPUES ON PUE_KEYPUE = MOV_KEYPUE
    LEFT JOIN LABPROD.NMLOIMSS ON IMS_KEYIMS = EMP_KEYIMS
    LEFT JOIN LABPROD.NMLOLOCP ON LOC_KEYLOC = EMP_KEYLOC
